CREATE TABLE public.fin_operation_start (id boolean PRIMARY KEY DEFAULT true CHECK(id),started_at timestamptz NOT NULL,started_by uuid NOT NULL);
GRANT SELECT ON public.fin_operation_start TO authenticated;
GRANT ALL ON public.fin_operation_start TO service_role;
ALTER TABLE public.fin_operation_start ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION private.fin_super(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT _uid IS NOT NULL AND private.is_active(_uid) AND (private.is_super_admin(_uid) OR EXISTS(SELECT 1 FROM public.profiles WHERE id=_uid AND is_system_admin=true)); $$;
REVOKE ALL ON FUNCTION private.fin_super(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.fin_super(uuid) TO authenticated;
CREATE POLICY fin_start_super_select ON public.fin_operation_start FOR SELECT TO authenticated USING(private.fin_super(auth.uid()));
ALTER TABLE public.bank_transactions ADD COLUMN IF NOT EXISTS operation_test boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS bank_tx_operation_time ON public.bank_transactions(operation_test,transaction_at DESC);
CREATE OR REPLACE FUNCTION public.fin_operation_status() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE s public.fin_operation_start; BEGIN IF NOT private.fin_super(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được xem mốc vận hành Tiền Về'; END IF; SELECT * INTO s FROM public.fin_operation_start WHERE id=true; RETURN jsonb_build_object('started_at',s.started_at,'started_by',s.started_by); END; $$;
REVOKE ALL ON FUNCTION public.fin_operation_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fin_operation_status() TO authenticated;
CREATE OR REPLACE FUNCTION public.fin_operation_begin(_confirm boolean) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE me uuid:=auth.uid(); ts timestamptz; BEGIN IF NOT private.fin_super(me) THEN RAISE EXCEPTION 'Chỉ Super Admin được bắt đầu vận hành Tiền Về'; END IF; IF _confirm IS DISTINCT FROM true THEN RAISE EXCEPTION 'Cần xác nhận trước khi bắt đầu vận hành'; END IF; PERFORM pg_advisory_xact_lock(741928301); IF EXISTS(SELECT 1 FROM public.fin_operation_start WHERE id=true) THEN RAISE EXCEPTION 'Tiền Về đã bắt đầu vận hành; không thể đặt lại mốc'; END IF; ts:=clock_timestamp(); INSERT INTO public.fin_operation_start(id,started_at,started_by) VALUES(true,ts,me); UPDATE public.bank_transactions SET operation_test=true WHERE transaction_at IS NULL OR transaction_at<ts; RETURN ts; END; $$;
REVOKE ALL ON FUNCTION public.fin_operation_begin(boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fin_operation_begin(boolean) TO authenticated;
CREATE OR REPLACE FUNCTION private.fin_operation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE ts timestamptz; BEGIN PERFORM pg_advisory_xact_lock(741928301); SELECT started_at INTO ts FROM public.fin_operation_start WHERE id=true; IF TG_OP='UPDATE' AND OLD.operation_test THEN NEW.operation_test:=true; END IF; IF ts IS NOT NULL AND (NEW.transaction_at IS NULL OR NEW.transaction_at<ts) THEN NEW.operation_test:=true; END IF; IF NEW.operation_test AND NEW.gmf_status IN('pending','sending') THEN IF TG_OP='INSERT' THEN RETURN NULL; ELSIF NEW.gmf_status IS DISTINCT FROM OLD.gmf_status THEN RETURN NULL; END IF; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION private.fin_operation_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER fin_operation_guard BEFORE INSERT OR UPDATE ON public.bank_transactions FOR EACH ROW EXECUTE FUNCTION private.fin_operation_guard();
CREATE OR REPLACE FUNCTION private.fin_can_see(_uid uuid,_tx uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT _uid IS NOT NULL AND private.is_active(_uid) AND EXISTS(SELECT 1 FROM public.bank_transactions t LEFT JOIN public.bank_accounts a ON a.id=t.bank_account_id WHERE t.id=_tx AND CASE WHEN t.operation_test THEN private.fin_super(_uid) ELSE (private.sig_can(_uid,'finance.incoming.manage') OR private.sig_can(_uid,'finance.incoming.reconcile') OR (t.source<>'bank' AND private.sig_can(_uid,'finance.incoming.manual_manage')) OR (CASE WHEN t.source='bank' THEN (private.sig_can(_uid,'finance.incoming.view') OR private.sig_can(_uid,'finance.incoming.claim')) AND coalesce(a.share_sale,false) ELSE private.sig_can(_uid,'finance.incoming.manual_view') END AND (t.claimed_by=_uid OR (t.claimed_by IS NULL AND t.status='unclaimed'))) OR (t.source<>'bank' AND t.created_by=_uid AND private.sig_can(_uid,'finance.incoming.manual_create') AND t.claimed_by IS NULL AND t.status='unclaimed')) END); $$;
CREATE OR REPLACE FUNCTION public.fin_incoming_stats(_src text DEFAULT NULL,_acc uuid DEFAULT NULL,_from timestamptz DEFAULT NULL,_to timestamptz DEFAULT NULL,_q text DEFAULT NULL,_sale uuid DEFAULT NULL) RETURNS TABLE(status text,source text,n bigint,total numeric) LANGUAGE sql STABLE SET search_path=pg_catalog,public AS $$ WITH search AS(SELECT CASE WHEN btrim(coalesce(_q,'')) ~ '^[0-9]+([.,][0-9]{3})*$' AND length(replace(replace(btrim(_q),'.',''),',',''))<=16 THEN replace(replace(btrim(_q),'.',''),',','')::numeric END amount,btrim(coalesce(_q,'')) text,public.fin_can_view_totals() totals) SELECT t.status,CASE WHEN t.source='bank' THEN 'bank' ELSE 'manual' END,count(*),coalesce(sum(t.amount) FILTER(WHERE s.totals OR t.claimed_by=auth.uid()),0) FROM public.bank_transactions t CROSS JOIN search s WHERE NOT t.operation_test AND t.cancelled_at IS NULL AND t.amount>0 AND (_src IS NULL OR t.source=_src) AND (_acc IS NULL OR t.bank_account_id=_acc) AND (_from IS NULL OR t.transaction_at>=_from) AND (_to IS NULL OR t.transaction_at<_to) AND (_sale IS NULL OR t.claimed_by=_sale) AND (s.text='' OR CASE WHEN s.amount IS NOT NULL THEN t.amount=s.amount ELSE t.description ILIKE '%'||s.text||'%' OR t.reference_number ILIKE '%'||s.text||'%' OR t.note ILIKE '%'||s.text||'%' OR t.customer ILIKE '%'||s.text||'%' END) GROUP BY 1,2; $$;
CREATE OR REPLACE FUNCTION public.fin_incoming_history_stats(_src text DEFAULT NULL,_acc uuid DEFAULT NULL,_from timestamptz DEFAULT NULL,_to timestamptz DEFAULT NULL,_q text DEFAULT NULL,_sale uuid DEFAULT NULL) RETURNS TABLE(status text,source text,n bigint,total numeric) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT private.fin_super(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được xem lịch sử kiểm thử'; END IF; RETURN QUERY WITH search AS(SELECT CASE WHEN btrim(coalesce(_q,'')) ~ '^[0-9]+([.,][0-9]{3})*$' AND length(replace(replace(btrim(_q),'.',''),',',''))<=16 THEN replace(replace(btrim(_q),'.',''),',','')::numeric END amount,btrim(coalesce(_q,'')) text) SELECT t.status,CASE WHEN t.source='bank' THEN 'bank' ELSE 'manual' END,count(*),coalesce(sum(t.amount),0) FROM public.bank_transactions t CROSS JOIN search s WHERE t.operation_test AND t.cancelled_at IS NULL AND t.amount>0 AND (_src IS NULL OR t.source=_src) AND (_acc IS NULL OR t.bank_account_id=_acc) AND (_from IS NULL OR t.transaction_at>=_from) AND (_to IS NULL OR t.transaction_at<_to) AND (_sale IS NULL OR t.claimed_by=_sale) AND (s.text='' OR CASE WHEN s.amount IS NOT NULL THEN t.amount=s.amount ELSE t.description ILIKE '%'||s.text||'%' OR t.reference_number ILIKE '%'||s.text||'%' OR t.note ILIKE '%'||s.text||'%' OR t.customer ILIKE '%'||s.text||'%' END) GROUP BY 1,2; END; $$;
REVOKE ALL ON FUNCTION public.fin_incoming_history_stats(text,uuid,timestamptz,timestamptz,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fin_incoming_history_stats(text,uuid,timestamptz,timestamptz,text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION private.fin_notification_visible(_tx uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT _tx IS NULL OR EXISTS(SELECT 1 FROM public.bank_transactions WHERE id=_tx AND (NOT operation_test OR private.fin_super(auth.uid()))); $$;
REVOKE ALL ON FUNCTION private.fin_notification_visible(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.fin_notification_visible(uuid) TO authenticated;
CREATE POLICY fin_test_notifications_select ON public.notifications AS RESTRICTIVE FOR SELECT TO authenticated USING(private.fin_notification_visible(bank_tx_id));